"use client";

/**
 * Separator: a thin dividing line.
 * Purpose: wraps Radix Separator. Generated by shadcn, then re-themed to Grove. Owner: design system.
 * Props: orientation ("horizontal" default | "vertical"), decorative (true by default).
 * Responsive: stretches to its container. Accessibility: decorative lines are hidden from screen
 *   readers; set decorative={false} only when the line carries meaning.
 * States: none. Dependencies: radix Separator, cn.
 * Tests: controls.test.tsx; Design Lab "Foundations" (S2-T07).
 * UX reference: ds-foundations, hairlines (--c-border).
 */
import { Separator as SeparatorPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function Separator({
  className,
  orientation = "horizontal",
  decorative = true,
  ...props
}: ComponentProps<typeof SeparatorPrimitive.Root>) {
  return (
    <SeparatorPrimitive.Root
      data-slot="separator"
      decorative={decorative}
      orientation={orientation}
      className={cn(
        "shrink-0 bg-line data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-px",
        className,
      )}
      {...props}
    />
  );
}

export { Separator };
